        \leq k \sum_i  \operatornamewithlimits{\mathbb{E}}\nolimits_{t}\insquare{z_i^4 \mid z\in P}\,.
    \end{split} 
    \addtocounter{equation}{1}\tag{\theequation}\label{eq:SS:LC:unconditionalMoment:CS}
\end{align*}
Where we use Cauchy--Schwarz in the last inequality. 
Moreover, for any $1\leq i\leq k$,  
\begin{align*}
