    \cdot \operatornamewithlimits{\mathbb{E}}\nolimits_{t}\insquare{z_i^4 \mid z\in P_j}
    \leq \max_{j} \operatornamewithlimits{\mathbb{E}}\nolimits_{t}\insquare{z_i^4 \mid z\in P_j} \,.
    \end{split}
    \addtocounter{equation}{1}\tag{\theequation}\label{eq:SS:LC:unconditionalMoment:AcrossLegs}
\end{align*} 
Fix any $1\leq i, j\leq k$.
In the remainder of the proof, we upper bound 
\[
    \operatornamewithlimits{\mathbb{E}}\nolimits_{t}\insquare{z_i^2 \mid z\in P_j}
    \quadtext{and}
    \operatornamewithlimits{\mathbb{E}}\nolimits_{t}\insquare{z_i^{\smash{4}} \mid z\in P_j}\,.
\]
We divide the upper bound into two cases.
\begin{enumerate}
    \item \textbf{Case A ($i=j$):}~~ In this case, $z_i=y_{\max}$ and, hence,
    \[
        \operatornamewithlimits{\mathbb{E}}\nolimits_{t}\insquare{z_i^2 \mid z\in P_j} = y_{\max}^2
        \quadtext{and}
        \operatornamewithlimits{\mathbb{E}}\nolimits_{t}\insquare{z_i^{\smash{4}} \mid z\in P_j} = y_{\max}^4 \,.
    \]
    \item \textbf{Case B ($i\neq j$):}~~ Observe that conditioned on $z\in P_j$, the distribution of $z_i$ is $\truncatedNormal{\mu_i(t)}{1}{(-\infty, y_{\max}]}$, \emph{i.e.}{}, the truncation of $\normal{\mu_i(t)}{1}$ to the set $(-\infty, y_{\max}]$.
    Next, we use the following fact which is proved in \cref{sec:proofof:fact:SS:LC:boundOnTruncatedMoments}.
    \begin{restatable}[]{fact}{factboundOnTruncatedMoments}
        \label{fact:SS:LC:boundOnTruncatedMoments}
        Fix $\mu,b\in \mathbb{R}$. It holds that 
        \[
            \operatornamewithlimits{\mathbb{E}}_{z\sim \normal{\mu}{1}}\insquare{z^2\mid z\leq b}
            \leq 2\inparen{1+\abs{b}+\abs{\mu}}^2
            \qquadtext{and}
            \operatornamewithlimits{\mathbb{E}}_{z\sim \normal{\mu}{1}}\insquare{z^{\smash{4}}\mid z\leq b}
            \leq 3\inparen{1+\abs{b}+\abs{\mu}}^4\,.
        \]
    \end{restatable} 
    In our setting this implies the following bounds
    \begin{align*}
        \operatornamewithlimits{\mathbb{E}}\nolimits_{t}\insquare{z_i^2 \mid z\in P_j} &\leq 
