\label{lem:convexPartitionLocalGrowth}
    Let $\hypo{P}$ be a convex $\alpha$-information preserving partition of $\mathbb{R}^d$.
    The log-likelihood function $\ensuremath{\mathscr{L}}_{\hypo{P}}(\mu)$ (\Cref{eq:convexPartitionNLL}) satisfies an $\inparen{\sqrt2\alpha, 2}$-local growth condition.

The first term in the gradient expression is simply our current iterate for the mean
and we can obtain an unbiased estimate of the second term by sampling $y\sim \truncatedNormal{\mu}{I}{P}$
where $P$ is a fresh observation.

The second moment of the gradient oracle can be upper bounded by
\[
    2\relax{\mu}_2^2 
    +
    2\operatornamewithlimits{\mathbb{E}}_{P\sim \coarseNormal{{\mu^\star}}{I}{\hypo{P}}}
    {
        \operatornamewithlimits{\mathbb{E}}_{\truncatedNormal{\mu}{I}{P}}\insquare{
            \relax{x}_2^2
        }
    }\,.
\]
The first term is at most $D^2$
and the second term can be upper bounded as follows.
\begin{align*}
    &\operatornamewithlimits{\mathbb{E}}_{P\sim \coarseNormal{{\mu^\star}}{I}{\hypo{P}}}
    {
        \operatornamewithlimits{\mathbb{E}}_{\truncatedNormal{\mu}{I}{P}}\insquare{
            \relax{x}_2^2
        }
    } \\
    &\qquad= \operatornamewithlimits{\mathbb{E}}_{P\sim \coarseNormal{{\mu^\star}}{I}{\hypo{P}}} \operatornamewithlimits{\mathbb{E}}_{x\sim \truncatedNormal{\mu}{I}{P}} \insquare{\relax{x}_2^2\cdot \mathbb{1}_{B_\infty(0, R)}}
    + \operatornamewithlimits{\mathbb{E}}_{P\sim \coarseNormal{{\mu^\star}}{I}{\hypo{P}}} \operatornamewithlimits{\mathbb{E}}_{x\sim \truncatedNormal{\mu}{I}{P}} \insquare{\relax{x}_2^2\cdot \mathbb{1}_{B_\infty(0, R)^c}} \\
    &\qquad= \operatornamewithlimits{\mathbb{E}}_{P\sim \coarseNormal{{\mu^\star}}{I}{\hypo{P}}} \operatornamewithlimits{\mathbb{E}}_{x\sim \truncatedNormal{\mu}{I}{P}} \insquare{\relax{x}_2^2\cdot \mathbb{1}_{B_\infty(0, R)}}
    + \operatornamewithlimits{\mathbb{E}}_{P\sim \coarseNormal{{\mu^\star}}{I}{\hypo{P}}} \operatornamewithlimits{\mathbb{E}}_{x\sim \truncatedNormal{{\mu^\star}}{I}{P}} \insquare{\relax{x}_2^2\cdot \mathbb{1}_{B_\infty(0, R)^c}}\,.
\end{align*}
{In the last step,
we use the fact that $\hypo{P}$ is an $R$-local partition so that every set 
such that $P\cap B_\infty(0, R)^c\neq \varnothing$ is a singleton.
This allows us to replace the expectation over each $\truncatedNormal{\mu}{I}{P}$
in the second term
with an expectation over $\truncatedNormal{{\mu^\star}}{I}{P}$,
as the distribution consists of a single point.}
We can then bound the first term using a deterministic bound
and the second term using the second moment of $\normal{{\mu^\star}}{I}$.
\begin{align*}
    &\operatornamewithlimits{\mathbb{E}}_{P\sim \coarseNormal{{\mu^\star}}{I}{\hypo{P}}} \operatornamewithlimits{\mathbb{E}}_{x\sim \truncatedNormal{\mu}{I}{P}} \insquare{\relax{x}_2^2\cdot \mathbb{1}_{B_\infty(0, R)}}
    + \operatornamewithlimits{\mathbb{E}}_{P\sim \coarseNormal{{\mu^\star}}{I}{\hypo{P}}} \operatornamewithlimits{\mathbb{E}}_{x\sim \truncatedNormal{{\mu^\star}}{I}{P}} \insquare{\relax{x}_2^2\cdot \mathbb{1}_{B_\infty(0, R)^c}}  \\
    &\qquad\qquad\leq\quad  dR^2 + \operatornamewithlimits{\mathbb{E}}_{x\sim \normal{{\mu^\star}}{I}}\insquare{\relax{x}_2^2} \\
    &\qquad\qquad=\quad  dR^2 + d + \relax{{\mu^\star}}_2^2 \\
    &\qquad\qquad=\quad  O(dR^2 + D^2)\,.
\end{align*}

\begin{align*}
            &\operatornamewithlimits{\mathbb{E}}_{P\sim \coarseNormal{{\mu^\star}}{I}{\hypo{P}}} \operatornamewithlimits{\mathbb{E}}_{x\sim \truncatedNormal{\mu}{I}{P}} \insquare{\relax{x}_2^2\cdot \mathbb{1}_{B_\infty(0, R)}}
            + \operatornamewithlimits{\mathbb{E}}_{P\sim \coarseNormal{{\mu^\star}}{I}{\hypo{P}}} \operatornamewithlimits{\mathbb{E}}_{x\sim \truncatedNormal{{\mu^\star}}{I}{P}} \insquare{\relax{x}_2^2\cdot \mathbb{1}_{B_\infty(0, R)^c}}  \\
