\caption{Iterative-PSGD($K, w_0, \varepsilon_0, g, \varepsilon$)}\label{alg:SGD-local-growth-convergence}
\begin{algorithmic}[1]
    \State \textbf{Input:} Projection access to feasible region $K$,
    initial point $w^{(0)}\in K$, 
    $\varepsilon_0\geq F(w^{(0)}) - F({w^\star})$,
    gradient oracle $g$ with $\operatornamewithlimits{\mathbb{E}}\insquare{\relax{g}_2^2}\leq G^2$,
    local growth rate $\eta > 0$,
    desired accuracy $\varepsilon > 0$
    \State \textbf{Output:} $2\varepsilon$-optimal solution with probability $0.99$
    \vspace{0.2em}
    \State Set $\tau \gets \ceil{\log_2(\nfrac{\varepsilon_0}\varepsilon)}$
    \vspace{0.2em}
    \State Set $D_0 \gets \frac{2\varepsilon_0}{\eta \sqrt{\varepsilon}}$
    \vspace{0.2em}
    \State Set $\upgamma_0 \gets \frac{\varepsilon_0}{100G^2\tau}$
    \vspace{0.2em}
    \State Set $T \gets \frac{40000 G^2 \tau^2}{\eta^2\varepsilon}$
    \vspace{0.2em}
    \For{$\ell=1,\ldots, \tau$}
        \State $\upgamma_\ell \gets 2^{-\ell}\upgamma_0$
        \State $D_\ell\gets 2^{-\ell}D_0$
        \State $w^{(\ell, 0)} \gets w^{(\ell-1)}$
        \For{$t=1, \dots, T$}
            \State $w^{(\ell, t)} \gets \Pi_{K\cap B(w^{(\ell-1)}, D_k)} \inparen{w^{(\ell, t-1)} - \upgamma_\ell\cdot g(w^{(\ell, t-1)})}$
        \EndFor
        \State $w^{(\ell)} \gets \frac1T \sum_{t=1}^T w^{(\ell, t)}$
    \EndFor
    \vspace{1em}
    \State \textbf{Return} $w^{(\tau)}$
\end{algorithmic}

