Recall that, for some $\upgamma\in (0,\nfrac{1}{2}]$ and $R\geq 2$, $\ensuremath{\mathscr{E}}=\ensuremath{\mathscr{E}}_{i,\upgamma,R}$ is the following event:
\[
    1 ~\leq~ 
    \frac{\inangle{x, \wh{w}_i}}{
        R\sqrt{\log{\nfrac{1}{\upgamma}}}
    }\,,
    ~
    \frac{\inangle{x, \wh{u}}}{
        2\sqrt{\log{\nfrac{1}{\upgamma}}}
    }
    ~\leq~ 2\,.
\]
Here $u\coloneqq v_i - \inangle{v_i,\wh{w}_i}\wh{w}_i$ is the component of $v_i$ orthogonal to $w_i$ {and $\widehat u$ the unit vector parallel to $u$}.
In the special case, where $v_i$ is parallel to $w_i$ (and, hence, $u=0$), the definition of $\ensuremath{\mathscr{E}}$ omits the bound on $\inangle{x, \wh{u}}.$

In this section, we prove that 
\[
    \Pr[\ensuremath{\mathscr{E}}] = \upgamma^{6+4R^2+\log{R}}\,.
\]
We will use the following standard facts.
\begin{fact}[E.g., Proposition 2.1.2 in \citet{vershynin2018high}]\label{fact:GaussianTail}
    The following tail bounds hold for all $z>0$
    \[
        \frac{e^{-z^2/2}}{\sqrt{2\uppi}}\inparen{\frac{1}{z} - \frac{1}{z^3}}
        \leq 
        \Pr_{x\sim \customcal{N}(0,1)}[x\geq z]
        \leq \frac{e^{-z^2/2}}{\sqrt{2\uppi}}\frac{1}{z}\,.
    \]
\end{fact}
We divide the proof into two parts.
First, we prove the statement when $v_i$ is not parallel to $w_i$.
Then, we extend the proof to the special case where $v_i$ is parallel to $w_i$.

\paragraph{Case A ($v_i$ is not parallel to $w_i$).}
    Since $\wh{u}$ is a projection of $v_i$ in a space orthogonal to $w_i$, $\wh{u}$ is orthogonal to $w_i$.
    Further since $x\sim \customcal{N}(0,I)$ and $\wh w_i, \wh u$ are orthonormal, 
    $\sinangle{x, \wh{w}_i}$ and $\sinangle{x, \wh{u}}$ are independent random variables with distributions $\sinangle{x, \wh{w}_i}\sim \customcal{N}(0,1)$ and $\sinangle{x, \wh{u}}\sim \customcal{N}(0,1)$.
    Now, \cref{fact:GaussianTail} implies that 
    \begin{align*}
        \Pr\insquare{
            \frac{
                \sinangle{x, \wh{w}_i}
            }{
                R\sqrt{\log{\nfrac{1}{\upgamma}}}
            }
            >
            2
        }
        &\leq \frac{\upgamma^{4R^2}}{\sqrt{2\uppi}} \cdot 
        \frac{1}{2R\sqrt{\log{\nfrac{1}{\upgamma}}}}\,,\\
        \Pr\insquare{
            \frac{
                \sinangle{x, \wh{w}_i}
            }{
                R\sqrt{\log{\nfrac{1}{\upgamma}}}
            } \geq 1
        }
        &\geq 
        \frac{\upgamma^{4R^2}}{\sqrt{2\uppi}} \cdot 
        \frac{1}{R\sqrt{\log{\nfrac{1}{\upgamma}}}} 
        \inparen{
            1 - \frac{1}{\inparen{
                R\sqrt{\log{\nfrac{1}{\upgamma}}}
            }^2}
        }
        \quad~~ \Stackrel{R\geq 2\,,~\upgamma\leq \nfrac{1}{2}}{\geq}\quad~~ 
        \frac{\upgamma^{4R^2}}{\sqrt{2\uppi}} \cdot 
        \frac{6}{10R\sqrt{\log{\nfrac{1}{\upgamma}}}} 
        \,.
    \end{align*} 
    Hence, 
    \[
        \Pr\insquare{
            \frac{\sinangle{x, \wh{w}_i}}{
                R\sqrt{\log{\nfrac{1}{\upgamma}}}
            } \in [1,2]
        }
        \geq \frac{\upgamma^{4R^2}}{\sqrt{2\uppi}} \cdot \frac{1}{10R\sqrt{\log{\nfrac{1}{\upgamma}}}}
        \,.
        \addtocounter{equation}{1}\tag{\theequation}\label{eq:SS:event:lb1}
    \]
    Analogously, \cref{fact:GaussianTail} implies that 
    \[
        \Pr\insquare{
            \frac{\sinangle{x, \wh{u}}}{
                2\sqrt{\log{\nfrac{1}{\upgamma}}}
            } \in [1,2]
        }
        \geq \frac{\upgamma^{16}}{\sqrt{2\uppi}} \cdot \frac{1}{20\sqrt{\log{\nfrac{1}{\upgamma}}}}
        \,.
        \addtocounter{equation}{1}\tag{\theequation}\label{eq:SS:event:lb2}
    \]
    Since $\sinangle{x, \wh{w}_i}$ and $\sinangle{x, \wh{u}}$ are independent random variables, it holds that 
    \[
        \Pr[\ensuremath{\mathscr{E}}]
        = 
        \Pr\insquare{
            1 ~\leq~ 
            \frac{\inangle{x, \wh{w}_i}}{
                R\sqrt{\log{\nfrac{1}{\upgamma}}}
            }\,,
            ~
            \frac{\inangle{x, \wh{u}}}{
                2\sqrt{\log{\nfrac{1}{\upgamma}}}
            }
            ~\leq~ 2
        }
        ~~\quad\Stackrel{
            \textup{\tagform@{\ref{eq:SS:event:lb1}}}\,,~
            \textup{\tagform@{\ref{eq:SS:event:lb2}}}
        }{\geq}\quad~~
        \frac{\upgamma^{16+4R^2}}{2\uppi}\cdot \frac{1}{200R\log{\nfrac{1}{\upgamma}}}\,.
    \]
    Since $\upgamma \leq \nfrac{1}{2}$, $2^{11}\geq {400\uppi}$, and $z\leq \inparen{{\log{\nfrac{1}{z}}}}^{-1}$ for any $z\in (0,1)$ it follows that 
    \[
        \Pr[\ensuremath{\mathscr{E}}]
        \geq 
        \upgamma^{28+4R^2+\log{R}}
        ~~~\Stackrel{(R\geq 1)}{\geq}~~~
        \upgamma^{28+5R^2}\,.
    \]

\paragraph{Case B ($v_i$ is parallel to $w_i$).}
    In this case, $\ensuremath{\mathscr{E}}$ is defined to be the following event
    \[
        1 ~\leq~ 
        \frac{\inangle{x, \wh{w}_i}}{
            R\sqrt{\log{\nfrac{1}{\upgamma}}}
        }
        ~\leq~ 2\,.
    \]
    Calculations from the previous case imply that 
    \[
        \Pr[\ensuremath{\mathscr{E}}]
        \geq 
        \frac{\upgamma^{4R^2}}{\sqrt{2\uppi}}\cdot \frac{1}{10R\sqrt{\log{\nfrac{1}{\upgamma}}}}\,.
    \]
    Since $\upgamma \leq \nfrac{1}{2}$, $2^5\geq \sqrt{2\uppi}\cdot 10$, and $z\leq \inparen{\sqrt{\log{\nfrac{1}{z}}}}^{-1}$ for any $z\in (0,1)$ it follows that 
    \[
        \Pr[\ensuremath{\mathscr{E}}]
        \geq 
        \upgamma^{6+4R^2+\log{R}}
        ~~~\Stackrel{(R\geq 1)}{\geq}~~~
        \upgamma^{6(1+R^2)}\,.
    \]


    Suppose $v_i$ is not parallel to $w_i$; we handle the edge case where $v_i$ is parallel to $w_i$ separately.
    Let $z_i$ be the component of $v_i$ orthogonal to $w_i$.
    Recall that for each $1\leq j\leq k$
    \begin{align*}
        \rho_{j,V}
        &= \mathrm{proj}_{{\rm span}(v_i,w_i)}(x)^\top v_j 
        = 
        \inangle{x,\wh{z}_i} \sinangle{v_j,\wh{z}_i}
        +
        \inangle{x,\wh{w}_i} \sinangle{v_j,\wh{w}_i}\,,\\
        \rho_{j,W}
        &= \mathrm{proj}_{{\rm span}(v_i,w_i)}(x)^\top w_j 
        = 
        \inangle{x,\wh{z}_i} \sinangle{w_j,\wh{z}_i}
        +
        \inangle{x,\wh{w}_i} \sinangle{w_j,\wh{w}_i}\,.
    \end{align*}
We divide the proof into three parts corresponding to the three claims.

\paragraph{Proof of Claim 1.}
    Observe that
    \begin{align*}
        \rho_{i,W} - \rho_{j,W}
        &=
        \inangle{x,\wh{w}_i}\sinangle{w_i - w_j, \wh{w}_i}
        +
        \inangle{x,\wh{z}_i}\sinangle{w_i - w_j, \wh{z}_i}\,.
    \end{align*}
    First, we lower-bound the first term conditioned on $\ensuremath{\mathscr{E}}$, 
    \begin{align*}
        \inangle{x,\wh{w}_i}\sinangle{w_i - w_j, \wh{w}_i}
        = \inangle{x,\wh{w}_i}
        \cdot 
        \frac{\relax{w_i}^2 - \sinangle{w_j,w_i}}{
            {\relax{w_i}_2}
        }
        \quad~~~\Stackrel{\rm \cref{asmp:SS:separationBoundedness}}{\geq}\quad~~~ \inangle{x,\wh{w}_i}\cdot c 
        ~~\quad\Stackrel{\rm\cref{def:SS:event}}{\geq}\quad~~ cR\sqrt{\log{\nfrac{1}{\upgamma}}}\,.
    \end{align*}
    Next, we upper-bound the absolute value of the second term conditioned on $\ensuremath{\mathscr{E}}$, 
    \begin{align*}
        \abs{\inangle{x,\wh{z}_i}\sinangle{w_i - w_j, \wh{z}_i}}
        \leq \abs{\inangle{x,\wh{z}_i}}\relax{w_i - w_j}
        \quad~~~\Stackrel{\rm\cref{asmp:SS:separationBoundedness}}{\leq}\quad~~~ \abs{\inangle{x,\wh{z}_i}}\cdot 2C  
        \quad~~\Stackrel{\rm\cref{def:SS:event}}{\leq}\quad~~ 
        8C \cdot \sqrt{\log{\nfrac{1}{\upgamma}}}\,.
    \end{align*}
    Therefore, it follows that, conditioned on $\ensuremath{\mathscr{E}}$,  
    \[
        \rho_{i,W} - \rho_{j,W} 
        \geq
            4(cR-8C)\cdot\sqrt{\log{\nfrac{1}{\upgamma}}}\,.
    \]
    Further, observe that 
    \begin{align*}
        \inparen{\rho_{i,V} - \rho_{j,V}}
        - \inparen{\rho_{i,W} - \rho_{j,W}}
        &= 
        \inangle{x,\wh{z}_i}
        \inparen{
            \sinangle{v_i - w_i, \wh{z}_i}
            + \sinangle{w_j - v_j, \wh{z}_i}
        }
        + \inangle{x,\wh{w}_i}
        \inparen{
            \sinangle{v_i - w_i, \wh{w}_i}
            + \sinangle{w_j- v_j, \wh{w}_i}
        }\,.
    \end{align*}
    Since $\relax{V-W}_F\leq \sfrac{c^3}{(3C)}$, the Cauchy--Schwarz inequality implies that
    \[
        \inparen{\rho_{i,V} - \rho_{j,V}}
        - \inparen{\rho_{i,W} - \rho_{j,W}}
        \leq \frac{4c^3}{3C}\,.
    \]
    Therefore, it follows that, conditioned on $\ensuremath{\mathscr{E}}$
    \[
        \rho_{i,V} - \rho_{j,V} 
        \geq 4\inparen{cR-8C-\frac{c^3}{3C}}\sqrt{\log{\nfrac{1}{\upgamma}}}
        ~~\quad \Stackrel{c\leq 1,~C\geq 1}{\leq}\quad~~ 
        4\inparen{cR-9C}\sqrt{\log{\nfrac{1}{\upgamma}}}\,.
    \]
    Finally, if $v_i$ is parallel to $w_i$, the result follows as a special case of the above since in that case $\rho_{i, W} - \rho_{j, W}
        =
        \inangle{x,\wh{w}_i}\sinangle{w_i - w_j, \wh{w}_i}$.

\paragraph{Proof of Claim 2.}
    Conditioned on $\ensuremath{\mathscr{E}}$ it follows that 
    \begin{align*}
        \abs{\rho_{j,V} - \rho_{j,W}}
        = \abs{
            \inangle{x,\wh{z}_i}\sinangle{v_j - w_j, \wh{z}_i}
            + 
            \inangle{x,\wh{w}_i}\sinangle{v_j - w_j, \wh{w}_i}
        }\,.
    \end{align*}
    Therefore, conditioned on \cref{def:SS:event}, 
    \begin{align*}
        \abs{\rho_{j,V} - \rho_{j,W}} 
        &\leq 2\sqrt{\log{\nfrac{1}{\upgamma}}}\cdot \abs{\sinangle{v_j - w_j, \wh{z}_i}}
        + 
        2R\sqrt{\log{\nfrac{1}{\upgamma}}}\cdot \abs{\sinangle{v_j - w_j, \wh{w}_i}}\,.
    \end{align*}
    Next, Cauchy--Schwarz inequality implies that 
    \[
        \abs{\rho_{j,V} - \rho_{j,W}}  \leq 2(1+R)\cdot \sqrt{\log{\nfrac{1}{\upgamma}}}\cdot \relax{v_j - w_j}_2\,.
        \addtocounter{equation}{1}\tag{\theequation}\label{eq:SS:propertiesOfRHO:UB1}
    \]
    Finally, in the special case where $v_i$ is parallel to $w_i$, the result follows as $\rho_{j,V} - \rho_{j,W}
        = {
            \inangle{x,\wh{w}_i}\sinangle{v_j - w_j, \wh{w}_i}
        }$ and one can verify that \cref{eq:SS:propertiesOfRHO:UB1} holds.

\paragraph{Proof of Claim 3.}
    Observe that 
    \[
        \abs{\rho_{i,V} - \rho_{i,W}}
        = \abs{\mathrm{proj}_{{\rm span}(v_i,w_i)}(x)^\top (v_i -w_i)}
        = 
        \abs{\inangle{x,\wh{z}_i} \sinangle{v_i -w_i,\wh{z}_i}
        +
        \inangle{x,\wh{w}_i} \sinangle{v_i -w_i,\wh{w}_i}}\,.
    \]
    Since $\wh{z}_i$ is orthogonal to $\wh{w}_i$ (by definition) and $v_i-w_i$ lies in ${\rm span}(z_i,w_i)$, it follows that 
    \[
        \abs{\rho_{i,V} - \rho_{i,W}}
        \geq 
        \abs{
            \min\inbrace{
            \inangle{x,\wh{z}_i},
            \inangle{x,\wh{w}_i}
            } 
            - 
            \min\inbrace{
                \inangle{x,\wh{z}_i},
                \inangle{x,\wh{w}_i}
            }
        }\cdot \relax{v_i - w_i}\,.
    \]
    Therefore, conditioned on $\ensuremath{\mathscr{E}}$,
    \[
        \abs{\rho_{i,V} - \rho_{i,W}}
        \geq (R-2)\sqrt{\log{\nfrac{1}{\upgamma}}}\cdot \relax{v_i - w_i}
        ~~~\Stackrel{(R\geq 12)}{\geq}~~~ \frac{5R\sqrt{\log{\nfrac{1}{\upgamma}}}}{6}\cdot \relax{v_i - w_i}\,.
    \]
    Finally, in the special case where $v_i$ is parallel to $w_i$, the result holds because 
    \[
        \abs{\rho_{i,V} - \rho_{i,W}}
        = \abs{\mathrm{proj}_{{\rm span}(v_i,w_i)}(x)^\top (v_i -w_i)}
        = x^\top \wh{w}_i \relax{v_i - w_i}_2
        ~~\quad\Stackrel{\rm\cref{def:SS:event}}{\geq}\quad~~ 2R\sqrt{\log{\nfrac{1}{\upgamma}}}\cdot \relax{v_i - w_i}_2\,.
    \]

\label{lem:SS:cdfRatiosLB}
                For each $\mu\neq 0$ and $\nu^2,\sigma^2 > 0$, it holds that:
                \[
                    \frac{
                        \Phi\inparen{\mu; \sigma^2}
                    }{
                        \Phi\inparen{0; \nu^2}
                    }\,,~ 
                    \frac{
                        \Phi\inparen{0; \nu^2}
                    }{
                        \Phi\inparen{\mu; \sigma^2}
                    }
                    ~~\notin~~ 
                    1\pm \frac{1}{\sqrt{2\uppi e}}
                    \min\inbrace{1, \frac{\abs{\mu}}{\sigma}}
                    \,.  
                \]

\label{lem:SS:cdfRatiosUB}
                Fix any $\alpha\geq 0$ and $\beta^2\in(0,1)$.
                For any $\lambda_1 \geq \lambda_2\geq 0$ and $\sigma_1^2,\sigma_2^2\geq 1$ such that 
                \[
                    \lambda_1 - \lambda_2 \leq \alpha
                    \qquadtext{and}
                    \frac{\sigma_1^2}{\sigma_2^2}\,,~\frac{\sigma_1^2}{\sigma_1^2} \in 1\pm \beta^2
                    \,,
                    \addtocounter{equation}{1}\tag{\theequation}\label{eq:SS:cdfRatiosUB:assumption}
                \]
                it holds that 
                \[
                    \frac{
                        \Phi\inparen{\lambda_1; \sigma_1^2}
                    }{
                        \Phi\inparen{\lambda_2; \sigma_2^2}
                    }\,,~ 
                    \frac{
                        \Phi\inparen{\lambda_2; \sigma_2^2}
                    }{
                        \Phi\inparen{\lambda_1; \sigma_1^2}
                    }
                    ~~\in~~ 
                    1\pm \beta^2 
                    \pm
                        \sqrt{\frac{8}{\uppi}}\frac{\alpha+\beta^2\lambda_1}{\min\inbrace{\sigma_1,\sigma_2}}
                        e^{-\frac{\lambda_2^2(1-\beta^2)}{2\max\sinbrace{\sigma_1^2,\sigma_2^2}}}
                        \,.
                \]

By definition,
\begin{align*}
    \Phi(\mu;\sigma^2) 
    &= \frac{1}{2} + \frac{\operatornamewithlimits{sgn}(\mu)}{\sqrt{2\uppi}\sigma} \int_{0}^{\abs{\mu}} e^{-z^2/(2\sigma^2)}{\rm d} z
    \geq \frac{1}{2} + \frac{
        \max_{0\leq z\leq \abs{\mu}} ze^{-z^2/(2\sigma^2)}
    }{\sqrt{2\uppi}\sigma}\,.
\end{align*}
Since $\Phi(0;\nu^2)=\nfrac{1}{2}$, 
\[
    \frac{\Phi(\mu;\sigma^2)}{\Phi(0;\nu^2)}
    \geq 1 + \sqrt{\frac{2}{\uppi}} \frac{
        \max_{0\leq z\leq \abs{\mu}} ze^{-z^2/(2\sigma^2)}
    }{\sigma}
    \,.
\]
Finally, as  
\[
    \sqrt{\frac{2}{\uppi}}\frac{
        \max_{0\leq z\leq \abs{\mu}} ze^{-z^2/(2\sigma^2)}
    }{\sigma}
    < \frac{1}{2}\,,
\]
and $\sfrac{1}{(1+z)} < 1-(\nfrac{z}{2})$ for all $0 < z < 1$, it follows that 
\[
    \frac{\Phi(0;\nu^2)}{\Phi(\mu;\sigma^2)}
    > 1 - \frac{1}{\sqrt{2\uppi}}\cdot \frac{\max_{0\leq z\leq \abs{\mu}} ze^{-z^2/(2\sigma^2)}}{\sigma}\,.
\]
The result follows from the following inequality (which can be checked by substitution)
\[
    \frac{
        \max_{0\leq z\leq \abs{\mu}} ze^{-z^2/(2\sigma^2)}
    }{
        \sigma 
    }
    \geq 
    \begin{cases}
        \frac{1}{\sigma\sqrt{e}}\cdot\abs{\mu} & \text{if } {\mu^2}\leq \sigma^2\\
        \frac{1}{\sqrt{e}} & \text{otherwise}
    \end{cases}
    \geq \frac{1}{\sqrt{e}} \min\inbrace{1, \frac{\abs{\mu}}{\sigma}}\,.
\]

Observe that 
\[
    \frac{\Phi(\lambda_1;\sigma_1^2)}{\Phi(\lambda_2;\sigma_2^2)}
    = \frac{
        \inparen{\nfrac{1}{\sigma_1}}\cdot \int_{-\infty}^{\lambda_1} e^{-\sfrac{z^2}{2\sigma_1^2}} {\rm d} z
    }{
        \inparen{\nfrac{1}{\sigma_2}}\cdot \int_{-\infty}^{\lambda_2} e^{-\sfrac{z^2}{2\sigma_2^2}} {\rm d} z
    }
    = \frac{\sigma_2}{\sigma_1}\cdot \frac{
        \inparen{\nfrac{1}{\sigma_2}}\cdot \int_{-\infty}^{\lambda_1\sigma_2/\sigma_1} e^{-\sfrac{z^2}{2\sigma_2^2}} {\rm d} z
    }{
        \inparen{\nfrac{1}{\sigma_2}}\cdot \int_{-\infty}^{\lambda_2} e^{-\sfrac{z^2}{2\sigma_2^2}} {\rm d} z
    }
    = \frac{\sigma_2}{\sigma_1}\cdot \frac{\Phi(\lambda_1\sigma_2/\sigma_1;\sigma_2^2)}{\Phi(\lambda_2;\sigma_2^2)}\,.
    \addtocounter{equation}{1}\tag{\theequation}\label{eq:SS:cdfRatiosUB:equality}
\]
Toward bounding this expression, we need to bound $\sfrac{\sigma_2}{\sigma_1}$ and $(\lambda_1\sigma_2/\sigma_1) - \lambda_2$:
First, by our assumptions, $\sfrac{\sigma_2^2}{\sigma_1^2}\in 1\pm \beta^2$, which implies that 
\[
    \frac{\sigma_2}{\sigma_1}\in 1\pm \beta^2\,,
    \addtocounter{equation}{1}\tag{\theequation}\label{eq:SS:cdfRatiosUB:varRatio}
\]
since $\sqrt{1\pm z^2}\in 1\pm z^2$ for any $z$ with $\abs{z}<1$.
Second 
\[
    \lambda_1\cdot \frac{\sigma_2}{\sigma_1}- \lambda_2
    ~~\Stackrel{\textup{\tagform@{\ref{eq:SS:cdfRatiosUB:varRatio}}}}{\in}~~ \lambda_1 - \lambda_2 \pm \beta^2 \lambda_1 
    ~~\Stackrel{\textup{\tagform@{\ref{eq:SS:cdfRatiosUB:assumption}}}}{\in}~~ [-\beta^2 \lambda_1 -\alpha,\alpha+\beta^2 \lambda_1 ]\,.
\]
Further, it holds that 
\begin{align*}
    \abs{\Phi(\lambda_1\sigma_2/\sigma_1;\sigma_2^2) 
    - \Phi\inparen{\lambda_2; \sigma_2^2}}
    &= \frac{1}{\sqrt{2\uppi}\sigma_2}\int_{\lambda_2}^{\sfrac{\lambda_1\sigma_2}{\sigma_1}} e^{-z^2/(2\sigma_2^2)}{\rm d} z
    \leq 
    \frac{\alpha+\beta^2\lambda_1 }{\sqrt{2\uppi}\sigma_2}
     e^{-\lambda_2^2(1-\beta^2)/(2\sigma_2^2)}\,. 
\end{align*}
Since $\Phi(0;\sigma_2^2)=\nfrac{1}{2}$,
$\lambda_2\geq 0$, and $\Phi(\cdot)$ is monotone and increasing, $\Phi(\lambda_2;\sigma_2^2)\geq \nfrac{1}{2}$.
Therefore, dividing by $\Phi(\lambda_2;\sigma_2^2)$ implies that 
\[
    1 
    - \sqrt{\frac{2}{\uppi}}\frac{\alpha+\beta^2\lambda_1}{\sigma_2}
     e^{-\lambda_2^2(1-\beta^2)/(2\sigma_2^2)}
    \leq 
    \frac{\Phi(\lambda_1\sigma_2/\sigma_1;\sigma_2^2) }{\Phi\inparen{\lambda_2; \sigma_2^2}}
    \leq 1 
    + \sqrt{\frac{2}{\uppi}}\frac{\alpha+\beta^2\lambda_1}{\sigma_2}
     e^{-\lambda_2^2(1-\beta^2)/(2\sigma_2^2)}\,.
\]
Combining this with \cref{eq:SS:cdfRatiosUB:equality,eq:SS:cdfRatiosUB:varRatio} and using that $1+\beta^2\leq 2$ implies that 
\[
    1 
    -\beta^2 - \sqrt{\frac{2}{\uppi}}\frac{\alpha+\beta^2\lambda_1}{\sigma_2}
     e^{-\lambda_2^2(1-\beta^2)/(2\sigma_2^2)}
    \leq 
    \frac{\Phi(\lambda_1;\sigma_1^2)}{\Phi(\lambda_2;\sigma_2^2)}
    \leq 1 
    + \beta^2 + \sqrt{\frac{8}{\uppi}}\frac{\alpha+\beta^2\lambda_1}{\sigma_2}
     e^{-\lambda_2^2(1-\beta^2)/(2\sigma_2^2)}\,.
\]
This implies part of the result.
It remains to bound $\sfrac{\Phi(\lambda_2;\sigma_2^2)}{\Phi(\lambda_1;\sigma_1^2)}$, which follows by replacing $\lambda_1,\lambda_2,\sigma_1,\sigma_2$ by $\lambda_2,\lambda_1,\sigma_2,\sigma_1$ respectively in the above proof.

\[
                    \frac{\Phi(\lambda_1;\sigma_1^2)}{\Phi(\lambda_2;\sigma_2^2)}
                    = \frac{
                        \inparen{\nfrac{1}{\sigma_1}}\cdot \int_{-\infty}^{\lambda_1} e^{-\sfrac{z^2}{2\sigma_1^2}} {\rm d} z
                    }{
                        \inparen{\nfrac{1}{\sigma_2}}\cdot \int_{-\infty}^{\lambda_2} e^{-\sfrac{z^2}{2\sigma_2^2}} {\rm d} z
                    }
                    = \frac{\sigma_2}{\sigma_1}\cdot \frac{
                        \inparen{\nfrac{1}{\sigma_2}}\cdot \int_{-\infty}^{\lambda_1\sigma_2/\sigma_1} e^{-\sfrac{z^2}{2\sigma_2^2}} {\rm d} z
                    }{
                        \inparen{\nfrac{1}{\sigma_2}}\cdot \int_{-\infty}^{\lambda_2} e^{-\sfrac{z^2}{2\sigma_2^2}} {\rm d} z
                    }
                    = \frac{\sigma_2}{\sigma_1}\cdot \frac{\Phi(\lambda_1\sigma_2/\sigma_1;\sigma_2^2)}{\Phi(\lambda_2;\sigma_2^2)}\,.
                    \addtocounter{equation}{1}\tag{\theequation}\label{eq:SS:cdfRatiosUB:equality}
                \]

\label{thm:convex body logconcave sampling}
        Consider a logconcave distribution $\uppi_f\propto e^{-f}$ over a convex body $K$.
        Suppose we are provided the following.
        \begin{enumerate}[label=(S\arabic*)]
            \item Zero-order access to $f$.
            \label[assumption]{assum:evaluation-oracle}
            \item Membership access to $K$.
            \label[assumption]{assum:membership-oracle}
            \item A point $x^{(0)}$ {and constants $R\geq r > 0$} such that $B_2(x^{(0)}, r)\subseteq K\subseteq B_2(x^0, R)$.
            \label[assumption]{assum:interior-point-oracle}
            \item A bound $M\geq \max_{x\in K} f(x) - f(x^\star)$.
            \label[assumption]{assum:range-oracle}
        \end{enumerate}
        Then, there is an algorithm that makes
        \[
            O\left( d^{4.5}\cdot \mathrm{polylog}(d, M, \nicefrac{R}r, \nicefrac1\delta) \right)
        \]
        membership oracle calls to produce a random vector within $\delta$-TV distance of $\uppi_f$.

\label{asmp:wellDescribedPolyhedron}
        Each observation $P\in \hypo{P}$ is a polyhedron and is provided in the form of a separation oracle and an upper bound $\varphi_P > 0$
        on the facet complexity of $P$.
